export function initShowcases({motionStopped}){
 const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
 $$('.product-showcase').forEach(root=>{const products=$$('.showcase-product',root);function select(product){products.forEach(p=>{const on=p===product;p.classList.toggle('is-open',on);$('.showcase-toggle',p).setAttribute('aria-expanded',String(on));$('.showcase-sign',p).textContent=on?'−':'＋';$('.showcase-fold',p).inert=!on;});document.dispatchEvent(new Event('showcasechange'));}products.forEach(p=>{const toggle=$('.showcase-toggle',p);toggle.addEventListener('click',()=>select(p));toggle.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'&&!root.contains(document.activeElement))select(p);});toggle.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();const i=e.key==='Home'?0:e.key==='End'?products.length-1:(products.indexOf(p)+(e.key==='ArrowDown'?1:-1)+products.length)%products.length;select(products[i]);$('.showcase-toggle',products[i]).focus();}});});});
 $$('.product-demo').forEach(demo=>{let step=0,visible=false,timer,manualPause=false;const scenes=$$('.demo-scene',demo),steps=$$('[data-demo-step]',demo),play=$('.demo-play',demo);function show(i){step=i;scenes.forEach((s,n)=>{s.hidden=n!==i;s.classList.toggle('is-active',n===i);});steps.forEach((s,n)=>{if(n===i)s.setAttribute('aria-current','step');else s.removeAttribute('aria-current');});}function sync(){clearInterval(timer);const stopped=motionStopped()||manualPause;play.textContent=stopped?'Play':'Pause';play.setAttribute('aria-label',stopped?'Play demonstration':'Pause demonstration');play.disabled=motionStopped();if(visible&&!document.hidden&&!stopped&&!demo.closest('[inert]'))timer=setInterval(()=>show((step+1)%scenes.length),3800);}steps.forEach((b,i)=>b.addEventListener('click',()=>{show(i);manualPause=true;sync();}));play.addEventListener('click',()=>{manualPause=!manualPause;sync();});demo.addEventListener('focusin',()=>clearInterval(timer));demo.addEventListener('focusout',e=>{if(!demo.contains(e.relatedTarget))sync();});new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;sync();},{threshold:.15}).observe(demo);['visibilitychange','motionchange','showcasechange'].forEach(e=>document.addEventListener(e,sync));sync();});
 $$('.work-carousel').forEach(carousel=>{const track=$('.work-track',carousel),slides=$$('.work-slide',track),prev=$('[data-carousel-prev]',carousel),next=$('[data-carousel-next]',carousel);let index=0,drag=null,moved=false;const width=()=>slides[1]?slides[1].offsetLeft-slides[0].offsetLeft:track.clientWidth;
 function update(){index=Math.max(0,Math.min(slides.length-1,Math.round(track.scrollLeft/width())));$('.carousel-count',carousel).textContent=`${String(index+1).padStart(2,'0')} / ${String(slides.length).padStart(2,'0')}`;$('.carousel-progress>span',carousel).style.width=`${(index+1)/slides.length*100}%`;prev.disabled=index===0;next.disabled=index===slides.length-1;}
 function go(i){track.scrollTo({left:width()*Math.max(0,Math.min(slides.length-1,i)),behavior:motionStopped()?'instant':'smooth'});}
 prev.addEventListener('click',()=>go(index-1));next.addEventListener('click',()=>go(index+1));track.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();go(e.key==='Home'?0:e.key==='End'?slides.length-1:index+(e.key==='ArrowRight'?1:-1));}});track.addEventListener('scroll',update,{passive:true});
 // Swipe depth: each visual drifts slightly against the swipe direction (touch, drag, arrows and keys alike).
 let depthQueued=false;const visuals=slides.map(slide=>$('.project-visual',slide));
 function paintDepth(){depthQueued=false;const box=track.getBoundingClientRect();slides.forEach((slide,i)=>{const offset=Math.max(-1,Math.min(1,(slide.getBoundingClientRect().left-box.left)/Math.max(1,box.width)));visuals[i]?.style.setProperty('--swipe-x',motionStopped()?'0px':`${(offset*-28).toFixed(1)}px`);});}
 track.addEventListener('scroll',()=>{if(!depthQueued){depthQueued=true;requestAnimationFrame(paintDepth);}},{passive:true});window.addEventListener('resize',update);
 track.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button===0){drag={x:e.clientX,left:track.scrollLeft,id:e.pointerId};moved=false;}});track.addEventListener('pointermove',e=>{if(!drag)return;const delta=e.clientX-drag.x;if(Math.abs(delta)>8){moved=true;track.classList.add('is-dragging');track.setPointerCapture(drag.id);track.scrollLeft=drag.left-delta;}});const end=()=>{if(drag){drag=null;track.classList.remove('is-dragging');if(moved)go(Math.round(track.scrollLeft/width()));}};track.addEventListener('pointerup',end);track.addEventListener('pointercancel',end);track.addEventListener('click',e=>{if(moved){e.preventDefault();e.stopPropagation();moved=false;}},true);track.addEventListener('dragstart',e=>e.preventDefault());
 $$('.project-visual',track).forEach(el=>{el.addEventListener('pointermove',e=>{if(motionStopped()||e.pointerType!=='mouse')return;const r=el.getBoundingClientRect();el.style.setProperty('--cursor-x',`${((e.clientX-r.left)/r.width-.5)*10}px`);el.style.setProperty('--cursor-y',`${((e.clientY-r.top)/r.height-.5)*8}px`);});el.addEventListener('pointerleave',()=>{el.style.setProperty('--cursor-x','0px');el.style.setProperty('--cursor-y','0px');});});update();});
}
